var (
	loadMu    sync.Mutex
	attempted bool
	lib       uintptr
	libErr    error
	libPath   string

	// ready is the fast path for checkLib: once the library has loaded
	// successfully, calls skip loadMu entirely.
	ready atomic.Bool

	// explicitLoad records that a successful Load acknowledged the current library.
	// It stays false while only the lazy path has opened it.
	explicitLoad bool

	// present records which symbols resolved during registerFuncs. It is
	// written under loadMu before ready is set, and only read afterwards.
	present = make(map[string]bool)

	// unbound records symbols the library exports that could not be bound,
	// keyed by symbol name. It follows the same locking discipline as present.
	unbound = make(map[string]error)
)

// SymbolError reports that a symbol is not callable.
//
// Err distinguishes the two ways that happens. A nil Err means the loaded
// library does not export the symbol, which is what an installation older
// than the symbol looks like. A non-nil Err means the library does export
// it and the binding itself failed; the library is not at fault.
type SymbolError struct {
	Symbol string
	Err    error
}

// Error reports the uncallable library symbol and, when the symbol was
// present but could not be bound, why.
func (e *SymbolError) Error() string {
	if e.Err != nil {
		return "nvrtc: symbol " + e.Symbol + " unavailable: " + e.Err.Error()
	}
	return "nvrtc: symbol " + e.Symbol + " unavailable"
}

// Unwrap returns the reason the symbol could not be bound, or nil when the
// loaded library does not export it.
func (e *SymbolError) Unwrap() error { return e.Err }

// LibraryConflictError reports a Load call naming a different library than
// the one already loaded. Only one library is loaded per process.
type LibraryConflictError struct {
	Loaded    string
	Requested string

	// Implicit reports that the loaded library was opened lazily and no
	// successful Load has since acknowledged it. A
	// caller that sees this called some
	// other function first, and that call took the default search list.
	Implicit bool
}

// Error reports the conflicting library paths, and whether the library
// that is already loaded got there without a Load call.
func (e *LibraryConflictError) Error() string {
	if e.Implicit {
		return fmt.Sprintf("nvrtc: an earlier call already loaded %q from the default search list, cannot load %q; call Load before any other function", e.Loaded, e.Requested)
	}
	return fmt.Sprintf("nvrtc: already loaded from %q, cannot load %q", e.Loaded, e.Requested)
}

// Load opens the shared library from path, or from the default search list
// when path is empty, and binds all symbols. Callers that need to direct
// loading should call Load before any other function; otherwise the first
// call loads from the default search list.
//
// Load is idempotent: calling it again with the same path, or with an empty
// path, returns nil. Calling it with a different path after a successful
// load returns *LibraryConflictError rather than replacing the library.
// After a failed load, Load retries.
func Load(path string) error {
	loadMu.Lock()
	defer loadMu.Unlock()
	if lib != 0 {
		if path != "" && path != libPath {
			return &LibraryConflictError{Loaded: libPath, Requested: path, Implicit: !explicitLoad}
		}
		explicitLoad = true
		return nil
	}
	attempted = false
	explicitLoad = true
	return loadLocked(path)
}

// Loaded reports whether the library is currently loaded. It does not
// trigger a load.
func Loaded() bool {
	return ready.Load()
}

// Path returns the path or name the loaded library was opened from,
// or the empty string if no library is loaded.
func Path() string {
	loadMu.Lock()
	defer loadMu.Unlock()
	return libPath
}

// Has reports whether the named C symbol resolved in the loaded library,
// loading it first if necessary. It returns false if the library failed to
// load. Use it to gate on capabilities before calling into them.
func Has(symbol string) bool {
	if err := checkLib(); err != nil {
		return false
	}
	return present[symbol]
}

// Close unloads the library and clears all bound function pointers.
//
// The function pointers are package-level state, so Close must not be
// called concurrently with any other call into this package: doing so is a
// use-after-free. It is intended for test teardown, not for reclaiming a
// live library.
func Close() error {
	loadMu.Lock()
	defer loadMu.Unlock()
	if lib == 0 {
		return nil
	}
	err := closeLibrary(lib)
	lib = 0
	libErr = nil
	libPath = ""
	attempted = false
	explicitLoad = false
	ready.Store(false)
	present = make(map[string]bool)
	unbound = make(map[string]error)
	clearFuncs()
	if err != nil {
		return fmt.Errorf("nvrtc: close: %w", err)
	}
	return nil
}

// loadLocked performs the one-time load. It must be called with loadMu held.
func loadLocked(path string) error {
	if attempted {
		return libErr
	}
	attempted = true
	if os.Getenv("CODEGEN_SKIP_BINDINGS") != "" {
		libErr = errors.New("nvrtc: bindings disabled via CODEGEN_SKIP_BINDINGS")
		return libErr
	}
	lib, libPath, libErr = openLibrary(path)
	if libErr != nil {
		return libErr
	}
	registerFuncs()
	if libErr = checkVersion(); libErr != nil {
		closeLibrary(lib)
		lib = 0
		libPath = ""
		present = make(map[string]bool)
		unbound = make(map[string]error)
		clearFuncs()
		return libErr
	}
	ready.Store(true)
	return nil
}

// VersionMismatchError reports that the shared library that opened is not
// from the version train nvrtc was generated for. dlsym matches on name
// alone, so a library from a neighbouring train opens and resolves nearly
// every symbol; asking it its own version is what tells the two apart.
type VersionMismatchError struct {
	Path string // the library that was opened
	Want int    // major version these bindings were generated for
	Got  int    // major version the library reports
	Raw  int    // the version value the library reported, undecoded
}

// Error reports which library was opened and the two majors that disagree.
//
// A decoder is only a decoder for the version schemes it was measured
// against, and a library from a train that predates the scheme can report
// a value it does not decode. Naming a major of 0 in that case would
// attribute to the library a claim it never made, so the raw value is
// reported instead.
func (e *VersionMismatchError) Error() string {
	if e.Got == 0 {
		return fmt.Sprintf("nvrtc: %s reported version %d, which does not decode as a version these bindings recognise; they require major %d", e.Path, e.Raw, e.Want)
	}
	return fmt.Sprintf("nvrtc: %s reports version major %d, these bindings require %d", e.Path, e.Got, e.Want)
}

// checkVersion asks the loaded library its version through nvrtcVersion and
// compares the major against 13, the soname major these bindings were
// generated against. It runs under loadMu, after registerFuncs, so it
// calls the bound pointer directly rather than the exported wrapper.
//
// A library that does not export the entry point, or that fails the call,
// is admitted. Absence is what an installation older than the entry point
// looks like, and refusing on it would reject working hosts to catch a
// case the soname already covers.
func checkVersion() error {
	if fnVersion == nil {
		return nil
	}
	var out0 int32
	var out1 int32
	if err := toError(fnVersion(&out0, &out1), "nvrtcVersion"); err != nil {
		return nil
	}
	raw := int(out0)
	got := raw
	switch got {
	case 13, 12:
	default:
		return &VersionMismatchError{Path: libPath, Want: 13, Got: got, Raw: raw}
	}
	return nil
}

// openLibrary attempts to load the nvrtc shared library and reports the
// path it was opened from. An explicit path wins; otherwise it checks the
// library path environment variable, then platform-specific default names.
func openLibrary(path string) (uintptr, string, error) {
	if path == "" {
		path = os.Getenv("NVRTC_LIB_PATH")
	}
	if path != "" {
		h, err := openDynamicLibrary(path)
		if err == nil {
			return h, path, nil
		}
		return 0, "", newLibraryError(path, []LibraryAttempt{{Name: path, Err: err}})
	}
	names := libraryNames()
	var attempts []LibraryAttempt
	for _, name := range names {
		h, err := openDynamicLibrary(name)
		if err == nil {
			return h, name, nil
		}
		attempts = append(attempts, LibraryAttempt{Name: name, Err: err})
	}
	return 0, "", newLibraryError("", attempts)
}

// LibraryAttempt records one failed attempt to open the shared library.
type LibraryAttempt struct {
	Name string // path or soname passed to dlopen
	Err  error
}

// LibraryError reports that libnvrtc could not be opened. Attempts lists
// every name tried in order. Path is set when an explicit path, from Load or
// NVRTC_LIB_PATH, was requested and failed. Hint, when non-empty, says where
// pkg-config believes the library is installed.
type LibraryError struct {
	Library  string
	Env      string
	Path     string
	Attempts []LibraryAttempt
	Hint     string
}

// Error describes the library load attempts and their errors.
func (e *LibraryError) Error() string {
	var b strings.Builder
	fmt.Fprintf(&b, "nvrtc: cannot open %s", e.Library)
	switch {
	case e.Path != "":
		fmt.Fprintf(&b, " at %s", e.Path)
	case len(e.Attempts) == 0:
		fmt.Fprintf(&b, ": no library names for %s/%s", runtime.GOOS, runtime.GOARCH)
	default:
		b.WriteString(": tried ")
		for i, a := range e.Attempts {
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteString(a.Name)
		}
	}
	if n := len(e.Attempts); n > 0 && e.Attempts[n-1].Err != nil {
		fmt.Fprintf(&b, ": %v", e.Attempts[n-1].Err)
	}
	if e.Hint != "" {
		b.WriteString("; " + e.Hint)
	}
	if e.Path == "" && e.Env != "" {
		fmt.Fprintf(&b, "; set %s to the library path", e.Env)
	}
	return b.String()
}

// Unwrap returns the error from each attempt.
func (e *LibraryError) Unwrap() []error {
	errs := make([]error, 0, len(e.Attempts))
	for _, a := range e.Attempts {
		if a.Err != nil {
			errs = append(errs, a.Err)
		}
	}
	return errs
}

func newLibraryError(path string, attempts []LibraryAttempt) *LibraryError {
	return &LibraryError{Library: "libnvrtc", Env: "NVRTC_LIB_PATH", Path: path, Attempts: attempts, Hint: pkgConfigHint()}
}

// pkgConfigHint asks pkg-config where the library is installed so that a
// load failure can say so. It runs only after every dlopen attempt has
// failed, never chooses the library, and is silent when pkg-config is
// absent or does not know the package.
func pkgConfigHint() string {
	const pkg = "nvrtc"
	exe, err := exec.LookPath("pkg-config")
	if err != nil {
		return ""
	}
	out, err := exec.Command(exe, "--variable=libdir", pkg).Output()
	if err != nil {
		return ""
	}
	dir := strings.TrimSpace(string(out))
	if dir == "" {
		return ""
	}
	return "pkg-config reports " + pkg + " in " + dir
}

// libraryNames returns the platform-specific shared library names to try.
func libraryNames() []string {
	switch runtime.GOOS {
	case "linux":
		return []string{"libnvrtc.so.13"}
	case "darwin":
		return []string{"libnvrtc.dylib"}
	case "windows":
		return []string{"nvrtc64_130_0.dll"}
	default:
		return nil
	}
}

// register uses purego to bind a Go function pointer to a symbol in the nvrtc
// library, recording whether the symbol resolved. Symbols absent from the
// loaded version are left unbound so the package still works against older
// releases; calling one returns *SymbolError rather than panicking.
func register(fn interface{}, symbol string) {
	if lib == 0 {
		return
	}
	sym, err := lookupLibrarySymbol(lib, symbol)
	if err != nil || sym == 0 {
		return
	}
	if !bindSymbol(fn, sym) {
		unbound[symbol] = errArgumentSlots
		return
	}
	present[symbol] = true
}

// errArgumentSlots is the reason a symbol the library exports could still
// not be bound: the signature needs more argument registers and stack slots
// than this architecture's calling convention provides.
var errArgumentSlots = errors.New("signature needs more argument slots than this architecture provides")

// bindSymbol binds fn to the resolved symbol address sym and reports whether
// the binding succeeded. purego.RegisterFunc panics when it cannot build a
// trampoline for fn's signature; the usual cause is a signature needing more
// argument registers and stack slots than the target architecture allows
// (purego admits 32 arguments on 64-bit platforms, 15 on ppc64le). Recovering
// leaves such a symbol unbound, so calling it reports *SymbolError, rather
// than killing the process at load time.
//
// purego assigns to fn only after every check it can panic on, so a recovered
// binding leaves fn nil.
func bindSymbol(fn interface{}, sym uintptr) (ok bool) {
	defer func() {
		if recover() != nil {
			ok = false
		}
	}()
	purego.RegisterFunc(fn, sym)
	return true
}

// registerSym resolves a symbol to its address and records whether it
// resolved. A symbol absent from the loaded version stays at zero, so
// calling it reports *SymbolError rather than jumping to address zero.
func registerSym(symbol string) uintptr {
	if lib == 0 {
		return 0
	}
	sym, err := lookupLibrarySymbol(lib, symbol)
	if err != nil || sym == 0 {
		return 0
	}
	present[symbol] = true
	return sym
}

// ffiCall0 through ffiCall6 hand a call to github.com/tmc/lib/nvidia/internal/ffi.
//
// Bit i of floatMask marks argument word i as a floating-point bit
// pattern, which the C ABI passes in a different register file from the
// integer and pointer words. Each returns the first integer result
// register and the first floating-point one; a caller reads whichever the
// C function sets.
//
// The //go:uintptrescapes directive is what makes a Go pointer safe to
// pass: a pointer converted to uintptr in one of these argument lists is
// moved to the heap and kept there until the call returns. A
// runtime.KeepAlive after the call would prevent reclamation but not
// movement, which is the failure this avoids.

//go:uintptrescapes
func ffiCall1(fn uintptr, floatMask uint32, a0 uintptr) (r1, rf uintptr) {
	var args [ffi.MaxArgs]uintptr
	args[0] = a0
	return ffi.CallFloat(fn, 1, &args, floatMask)
}

//go:uintptrescapes
func ffiCall2(fn uintptr, floatMask uint32, a0, a1 uintptr) (r1, rf uintptr) {
	var args [ffi.MaxArgs]uintptr
	args[0] = a0
	args[1] = a1
	return ffi.CallFloat(fn, 2, &args, floatMask)
}

//go:uintptrescapes
func ffiCall3(fn uintptr, floatMask uint32, a0, a1, a2 uintptr) (r1, rf uintptr) {
	var args [ffi.MaxArgs]uintptr
	args[0] = a0
	args[1] = a1
	args[2] = a2
	return ffi.CallFloat(fn, 3, &args, floatMask)
}

//go:uintptrescapes
func ffiCall6(fn uintptr, floatMask uint32, a0, a1, a2, a3, a4, a5 uintptr) (r1, rf uintptr) {
	var args [ffi.MaxArgs]uintptr
	args[0] = a0
	args[1] = a1
	args[2] = a2
	args[3] = a3
	args[4] = a4
	args[5] = a5
	return ffi.CallFloat(fn, 6, &args, floatMask)
}

// An outSlot pools the heap cells a wrapper passes to C for its outputs.
//
// A pointer passed through a positional call is moved to the heap, so the
// address of a local output variable would be one allocation per call. A
// pooled cell is already on the heap, where it never moves, and is reused.
// put clears the cell before returning it, so no output outlives its call.
type outSlot[T any] struct{ pool sync.Pool }

func (s *outSlot[T]) get() *T {
	if p, ok := s.pool.Get().(*T); ok {
		return p
	}
	return new(T)
}

func (s *outSlot[T]) put(p *T) {
	var zero T
	*p = zero
	s.pool.Put(p)
}

// BindFailure names a symbol the loaded library exports but that could not
// be bound, and why.
type BindFailure struct {
	Symbol string
	Err    error
}

// BindFailures returns the symbols the loaded library exports that could
// not be bound, sorted by symbol name, or nil if every exported symbol
// bound. Calling one of these reports *SymbolError with the same Err.
//
// A load that reports no error can still leave symbols unbound: the
// library is fine and the signatures are not representable here. Call this
// after Load to find that out at once rather than one call site at a time.
// It does not trigger a load, and returns nil if none has happened.
func BindFailures() []BindFailure {
	loadMu.Lock()
	defer loadMu.Unlock()
	if len(unbound) == 0 {
		return nil
	}
	out := make([]BindFailure, 0, len(unbound))
	for sym, err := range unbound {
		out = append(out, BindFailure{Symbol: sym, Err: err})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Symbol < out[j].Symbol })
	return out
}

// ptrAdd advances a byte pointer by n bytes.
func ptrAdd(p *byte, n int) unsafe.Pointer {
	return unsafe.Add(unsafe.Pointer(p), n)
}

// checkLib loads the library if it has not been loaded yet and returns the
// load error, if any.
func checkLib() error {
	if ready.Load() {
		return nil
	}
	loadMu.Lock()
	defer loadMu.Unlock()
	return loadLocked("")
}

// checkLibSym loads the library if necessary and reports whether symbol is
// callable. It returns the load error if the library is unavailable, or
// *SymbolError if the library loaded but symbol is not callable.
func checkLibSym(symbol string) error {
	if err := checkLib(); err != nil {
		return err
	}
	if !present[symbol] {
		return &SymbolError{Symbol: symbol, Err: unbound[symbol]}
	}
	return nil
}

// registerFuncs binds all raw function pointers to their library symbols.
func registerFuncs() {
	register(&fnGetErrorString, "nvrtcGetErrorString")
	symaddNameExpression = registerSym("nvrtcAddNameExpression")
	symcompileProgram = registerSym("nvrtcCompileProgram")
	symCreateProgram = registerSym("nvrtcCreateProgram")
	symdestroyProgram = registerSym("nvrtcDestroyProgram")
	symGetBundledHeadersInfo = registerSym("nvrtcGetBundledHeadersInfo")
	symgetCUBIN = registerSym("nvrtcGetCUBIN")
	symgetCUBINSize = registerSym("nvrtcGetCUBINSize")
	symgetLTOIR = registerSym("nvrtcGetLTOIR")
	symgetLTOIRSize = registerSym("nvrtcGetLTOIRSize")
	symgetLoweredName = registerSym("nvrtcGetLoweredName")
	symGetNumSupportedArchs = registerSym("nvrtcGetNumSupportedArchs")
	symgetOptiXIR = registerSym("nvrtcGetOptiXIR")
	symgetOptiXIRSize = registerSym("nvrtcGetOptiXIRSize")
	symgetPCHCreateStatus = registerSym("nvrtcGetPCHCreateStatus")
	symGetPCHHeapSize = registerSym("nvrtcGetPCHHeapSize")
	symgetPCHHeapSizeRequired = registerSym("nvrtcGetPCHHeapSizeRequired")
	symgetPTX = registerSym("nvrtcGetPTX")
	symgetPTXSize = registerSym("nvrtcGetPTXSize")
	symgetProgramLog = registerSym("nvrtcGetProgramLog")
	symgetProgramLogSize = registerSym("nvrtcGetProgramLogSize")
	symGetSupportedArchs = registerSym("nvrtcGetSupportedArchs")
	symgetTileIR = registerSym("nvrtcGetTileIR")
	symgetTileIRSize = registerSym("nvrtcGetTileIRSize")
	symInstallBundledHeaders = registerSym("nvrtcInstallBundledHeaders")
	symRemoveBundledHeaders = registerSym("nvrtcRemoveBundledHeaders")
	symsetFlowCallback = registerSym("nvrtcSetFlowCallback")
	symSetPCHHeapSize = registerSym("nvrtcSetPCHHeapSize")
	register(&fnVersion, "nvrtcVersion")
}

// clearFuncs unbinds all raw function pointers.
func clearFuncs() {
	fnGetErrorString = nil
	symaddNameExpression = 0
	symcompileProgram = 0
	symCreateProgram = 0
	symdestroyProgram = 0
	symGetBundledHeadersInfo = 0
	symgetCUBIN = 0
	symgetCUBINSize = 0
	symgetLTOIR = 0
	symgetLTOIRSize = 0
	symgetLoweredName = 0
	symGetNumSupportedArchs = 0
	symgetOptiXIR = 0
	symgetOptiXIRSize = 0
	symgetPCHCreateStatus = 0
	symGetPCHHeapSize = 0
	symgetPCHHeapSizeRequired = 0
	symgetPTX = 0
	symgetPTXSize = 0
	symgetProgramLog = 0
	symgetProgramLogSize = 0
	symGetSupportedArchs = 0
	symgetTileIR = 0
	symgetTileIRSize = 0
	symInstallBundledHeaders = 0
	symRemoveBundledHeaders = 0
	symsetFlowCallback = 0
	symSetPCHHeapSize = 0
	fnVersion = nil
}

